const STATION_MAPS_SET=new Set(['estacion_villa','estacion_quilpue','estacion_vina','estacion_valpo']);
// Tiles SÓLIDOS específicos del BuinZoo (animales/recintos/bancas), pese a ser walkable en otros mapas
const BUINZOO_SOLID=new Set(['t','p','r','l','e','m','f','o','j','k','b','W','I','S','B']);
const updateCamera=()=>{ const m=MAPS[currentMap],mW=m[0].length,mH=m.length; camera.x=Math.max(0,Math.min(player.x-4,mW-10)); camera.y=Math.max(0,Math.min(player.y-4,mH-10)); };
let _suppressOrigin=false;
const transitionTo=(id,tx,ty)=>{
  if(!_suppressOrigin && currentMap!==id && currentMap!=='laboratorio' && currentMap!=='taller') progress._origin={map:currentMap,x:player.x,y:player.y};
  if(currentMap==='sala_cont')stopSalaContMusic();
  setTimeout(()=>Music.play(id),200);
  // COVID entry message (first visit)
  currentMap=id; player.x=tx; player.y=ty; player.steps=0; updateCamera();
  // Pre-render static tiles to offscreen canvas on map change
  if(MAPS[id]&&typeof window!=='undefined'&&typeof drawMap==='function'){
    const fn=drawMap._fnMap?.[id];
    if(fn&&!TileCache.get(id)) setTimeout(()=>TileCache.prerender(id,MAPS[id],fn),50);
  }
  window.__v4Transicion?.(id,tx,ty); // avisa al motor nuevo
  setTimeout(()=>{ const msg=COVID_ENTRY_MSGS[currentMap]; if(msg&&STATE==='exploring'){const txt=msg();if(txt)setTimeout(()=>showDialog(txt),100);} },500);
};

